// ─── readOnly: skip dirty checking, route to replica ───
@Service
@Transactional(readOnly = true)  // class-level: all methods = read-only
public class ReportService {

    public PortfolioReport getReport(String accountId) {
        // Hibernate: flush mode = MANUAL (no dirty check — faster)
        // DataSource: routed to READ REPLICA (if routing configured)
        return portfolioRepo.generateReport(accountId);
    }

    @Transactional  // override: writable TX for this method only
    public void updateReport(String reportId) { /* writes allowed */ }
}

// ─── @TransactionalEventListener phases ───
@Component
public class TransferEventListeners {

    @TransactionalEventListener(phase = TransactionPhase.BEFORE_COMMIT)
    public void beforeCommit(TransferEvent event) {
        // Last chance to add work to the TX (e.g., validation)
        // If this throws → TX rolls back
    }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)  // DEFAULT
    public void afterCommit(TransferEvent event) {
        // TX is committed. Safe for: email, SMS, Kafka publish, cache invalidation.
        smsService.send(event.phone(), "Transfer completed");
    }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_ROLLBACK)
    public void afterRollback(TransferEvent event) {
        // TX rolled back. Alert ops or log failure.
        alertService.send("Transfer failed for " + event.accountId());
    }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMPLETION)
    public void afterCompletion(TransferEvent event) {
        // Fires regardless of commit or rollback. Cleanup.
    }

    // fallbackExecution=true: fires even outside a TX context
    @TransactionalEventListener(fallbackExecution = true)
    public void alwaysFires(TransferEvent event) {
        // If event published outside @Transactional → still fires
    }
}
